  "logic:extreme:#dz1pk5": {"cs":"Včelí plástve tvoří šestiúhelníky – ze všech tvarů potřebují na uzavření daného prostoru nejméně vosku.","src":"Wikipedie: Šestiúhelník"},
  "logic:extreme:#e7wp2h": {"cs":"Tranzitivita: když A⊆B a B⊆C, pak A⊆C — základ sylogismu.","src":"Wikipedie: Tranzitivní relace"},
  "logic:extreme:#eakeev": {"cs":"Staří Egypťané používali téměř výhradně jednotkové zlomky (1/n); výjimkou byl zlomek 2/3.","src":"Wikipedie: Egyptské zlomky"},
  "logic:extreme:#ejo99a": {"cs":"Čísla 7, 19, 23 a 31 jsou všechna prvočísla – dají se dělit jen 1 a sebou samými.","src":"Wikipedie: Prvočíslo"},
  "logic:extreme:#gi9im1": {"en":"Did you know? Hexadecimal uses 0–9 then A–F, so 'FF' equals 255 in decimal.","src":"Wikipedia: Hexadecimal"},
  "logic:extreme:#hjghk3": {"cs":"2^10 = 1024 se rovná počtu bajtů v jednom kibibajtu (dříve nesprávně označovaném 1 kB).","src":"Wikipedie: Kibibajt"},
  "logic:extreme:#k3o8d3": {"cs":"Součet 180° platí jen v rovině; na zakřiveném povrchu (např. na kouli) může být součet vnitřních úhlů větší.","src":"Wikipedie: Trojúhelník"},
