  "logic:extreme:#s0kmln": {"cs":"Šestnáctková soustava používá 0–9 a A–F, proto se jí říká hexadecimální.","src":"Wikipedie: Šestnáctková soustava"},
  "logic:extreme:#sns87": {"cs":"Úplný graf s n vrcholy má přesně n(n−1)/2 hran – pro 10 vrcholů je to 45 hran.","src":"Wikipedie: Úplný graf"},
  "logic:extreme:#u9s70g": {"en":"Did you know? The square root of 2 was the first number proven irrational, around 500 BC, reportedly by Hippasus of Metapontum.","src":"Wikipedia: Square root of 2"},
