  "logic:hard:#14w9w0g": {"cs":"Mocniny dvojky (2, 4, 8, 16, 32, 64, 128, 256, 512, 1024) pohánějí počítače – odtud 8bitová a 32bitová čísla.","src":"Wikipedie: Umocňování"},
  "logic:hard:#168zrmj": {"cs":"Slovo „procento“ pochází z latinského per centum, tedy „ze sta“; 25 % je přesně jedna čtvrtina.","src":"Wikipedie: Procento"},
