  "logic:hard:#1gsr6xp": {"cs":"Fibonacciho čísla 1, 2, 3, 5, 8, 13, 21… se objevují v přírodě, například ve spirálách slunečnice či šišky.","src":"Wikipedie: Fibonacciho posloupnost"},
  "logic:hard:#1hdvb2c": {"cs":"Víš, že obdélníky 6 × 2 a 5 × 3 mají stejný obvod (16), ale různý obsah (12 a 15)?","src":"Wikipedie: Obdélník"},
