  "logic:hard:#1ywryo8": {"cs":"Víš, že staří Egypťané používali jen zlomky s čitatelem 1 (tzv. kmenné zlomky), například 1/2 nebo 1/7?","src":"Wikipedie: Egyptské zlomky"},
  "logic:hard:#3t8ai9": {"cs":"Víš, že slovo algebra pochází z arabského 'al-džabr' (spojování), z díla matematika al-Chvárizmího?","src":"Wikipedie: Algebra"},
