  "logic:hard:#kxmss5": {"cs":"Číslo 9 je dělitelné 3, proto není prvočíslo. Prvočíslo má jen dva dělitele: 1 a sebe.","src":"Wikipedie: Prvočíslo"},
  "logic:hard:#lk84qf": {"en":"Did you know? A kilometre is 1,000,000 millimetres — the prefix 'kilo-' always means one thousand.","src":"Wikipedia: Metric prefix"},
  "logic:hard:#met6he": {"cs":"Víš, že nuly na konci desetinného čísla nic nemění? 0,5 a 0,50 jsou přesně stejně velká čísla.","src":"Wikipedie: Desetinné číslo"},
  "logic:hard:#nqpyhm": {"cs":"Víš, že při dělení má každé číslo své jméno? Dělenec : dělitel = podíl, např. 12 : 4 = 3 a 3 je podíl.","src":"Wikipedie: Dělení"},
  "logic:hard:#q2an8r": {"cs":"Součet všech vnitřních úhlů trojúhelníku je vždy přesně 180 stupňů – ať je jakkoli velký nebo tvarovaný.","src":"Wikipedie: Trojúhelník"},
  "logic:hard:#q65skk": {"en":"Did you know? This is the Fibonacci sequence: each number is the sum of the two before it (1+1=2, 1+2=3, 2+3=5...).","src":"Wikipedia: Fibonacci number"},
  "logic:hard:#qywlpy": {"cs":"Jednička není prvočíslo – prvočíslo má právě dva dělitele. Nejmenší prvočíslo je 2 a je jediné sudé.","src":"Wikipedie: Prvočíslo"},
  "logic:hard:#rj3ikb": {"cs":"Nejmenší prvočíslo je 2 – je to jediné sudé prvočíslo.","src":"Wikipedie: Prvočíslo"},
  "logic:hard:#rtxikq": {"en":"Did you know? Inductive reasoning generalises from observations; deductive reasoning works the other way, from general rules to specific cases.","src":"Wikipedia: Inductive reasoning"},
  "logic:hard:#sfndl6": {"en":"Did you know? 6 L per 100 km over 250 km is 6 × 2.5 = 15 L of fuel.","src":"Wikipedia: Fuel economy in automobiles"},
  "logic:hard:#svrevz": {"en":"Did you know? Solving x + 5 = 12 means subtracting 5 from both sides to get x = 7.","src":"Wikipedia: Equation solving"},
